class Solution:
    def isValid(self, s: str) -> bool:
        matching_open = {')': '(', ']': '[', '}': '{'}
        stack = []
        for ch in s:
            if ch not in matching_open:
                stack.append(ch)
            else:
                if not stack or stack.pop() != matching_open[ch]:
                    return False
        return not stack
